diff --git a/backend/src/Modules/SemanticQuery/OntologyPlatform.Modules.SemanticQuery/G4QueryKeyEquality.cs b/backend/src/Modules/SemanticQuery/OntologyPlatform.Modules.SemanticQuery/G4QueryKeyEquality.cs
